void require(bool okay,const std::string& message){if(!okay)throw std::runtime_error("INCONCLUSIVE resolved-normal: "+message);}
void glOkay(const std::string& label){const auto error=glGetError();require(error==GL_NO_ERROR,label+" GL error "+std::to_string(error));}
std::string readText(const fs::path& path){std::ifstream input(path,std::ios::binary);require(bool(input),"cannot read "+path.string());return {std::istreambuf_iterator<char>(input),{}};}
void writeText(const fs::path& path,const std::string& text){std::ofstream out(path,std::ios::binary);out<<text;require(bool(out),"cannot save "+path.string());}
void writeRaw(const fs::path& path,const std::vector<float>& values){std::ofstream out(path,std::ios::binary);out.write(reinterpret_cast<const char*>(values.data()),std::streamsize(values.size()*sizeof(float)));require(bool(out),"cannot save "+path.string());}
std::string quote(const std::string& text){std::ostringstream out;out<<'"';for(unsigned char c:text){if(c=='"'||c=='\\')out<<'\\'<<c;else if(c<' ')out<<"\\u"<<std::hex<<std::setw(4)<<std::setfill('0')<<int(c)<<std::dec;else out<<c;}out<<'"';return out.str();}
