std::string observed(const std::string& original){
    auto source=original;const std::string begin="\n// RESOLVED_NATIVE_STORE_BEGIN\n",end="// RESOLVED_NATIVE_STORE_END\n";
    const auto insertAfter=[&](const std::string& anchor,const std::string& payload){auto at=source.find(anchor);require(at!=std::string::npos&&source.find(anchor,at+anchor.size())==std::string::npos,"STORE seam absent/ambiguous");source.insert(at+anchor.size(),begin+payload+end);};
    insertAfter("void main() {\n","    vec3 OBS_preNormal=vec3(0.0); float OBS_grazing=-1.0;\n");
    insertAfter("    if (dot(n,geometricNormal)<0.0) n=-n;\n","    OBS_preNormal=n;\n");
    insertAfter("        float resolved=smoothstep(minimumCosine,minimumCosine+0.12,dot(n,v));\n","        OBS_grazing=resolved;\n");
    const auto finalStore=[&](const std::string& anchor,const std::string& finish,const std::string& payload){auto at=source.find(anchor);require(at!=std::string::npos&&source.find(anchor,at+anchor.size())==std::string::npos,"final STORE seam changed");at=source.find(finish,at+anchor.size());require(at!=std::string::npos,"final STORE terminator absent");source.insert(at,begin+payload+end);};
    std::string zero;for(int i=1;i<outputs;++i)zero+="    gl_FragData["+std::to_string(i)+"]=vec4(0.0);\n";
    finalStore("        gl_FragData[0]=vec4(lit,tex.a);\n","        return;",zero);
    finalStore("    gl_FragData[0]=vec4(max(color,vec3(0.0)),1.0);\n","\n}",
        "    gl_FragData[1]=vec4(OBS_preNormal,1.0);\n"
        "    gl_FragData[2]=vec4(n,OBS_grazing);\n"
        "    gl_FragData[3]=vec4(wave.yz,max(footprint*1.25,0.035),slopeVariance);\n"
        "    gl_FragData[4]=vec4(worldPosition,waterMeanSurfaceY);\n"
        "    gl_FragData[5]=vec4(float(localColumnKnown),float(upperSurface),float(underwater),1.0);\n"
        "    gl_FragData[6]=vec4(geometricNormal,waterUnknownWeight);\n"
        "    gl_FragData[7]=vec4(normalVariance,roughness,footprint,1.0);\n");
    auto recovered=source;for(auto at=recovered.find(begin);at!=std::string::npos;at=recovered.find(begin)){auto finish=recovered.find(end,at);require(finish!=std::string::npos,"malformed STORE marker");recovered.erase(at,finish+end.size()-at);}
    require(recovered==original,"STORE removal must recover byte-identical original expanded main");return source;
}
GLuint makeProgram(const std::vector<std::pair<GLenum,std::string>>& sources,const std::string& name,std::ostringstream& report,bool feedback=false){
    const auto id=glCreateProgram();std::vector<GLuint> stages;for(const auto& source:sources){const auto stage=compile(source.first,source.second,name+"-"+std::to_string(source.first));stages.push_back(stage);glAttachShader(id,stage);}glBindAttribLocation(id,10,"mc_Entity");
    const char* fields[]={"gl_Position","worldPosition","waterMeanSurfaceY","waterUnknownWeight","materialId"};if(feedback)glTransformFeedbackVaryings(id,5,fields,GL_INTERLEAVED_ATTRIBS);glLinkProgram(id);GLint linked=0;glGetProgramiv(id,GL_LINK_STATUS,&linked);if(!linked){char log[16384]={};glGetProgramInfoLog(id,sizeof(log),nullptr,log);throw std::runtime_error(name+": "+log);}
    require(glGetAttribLocation(id,"mc_Entity")==10,"material attribute location differs");GLint count=0;glGetProgramiv(id,GL_ATTACHED_SHADERS,&count);require(count==GLint(sources.size()),"actual attached-stage count differs");std::vector<GLuint> attached(std::size_t(count),0);GLsizei actual=0;glGetAttachedShaders(id,count,&actual,attached.data());require(actual==count,"attached reflection count differs");
    std::vector<GLint> types,expected;for(auto stage:attached){GLint type=0;glGetShaderiv(stage,GL_SHADER_TYPE,&type);types.push_back(type);}for(const auto& source:sources)expected.push_back(GLint(source.first));std::sort(types.begin(),types.end());std::sort(expected.begin(),expected.end());require(types==expected,"actual attached-stage types differ");
    report<<"{\"name\":"<<quote(name)<<",\"linked\":true,\"stage_types\":[";for(std::size_t i=0;i<types.size();++i){if(i)report<<',';report<<types[i];}report<<']';
    if(sources.size()==4){const std::array<std::pair<GLenum,GLint>,5> layout={{{GL_TESS_CONTROL_OUTPUT_VERTICES,3},{GL_TESS_GEN_MODE,GL_TRIANGLES},{GL_TESS_GEN_SPACING,GL_EQUAL},{GL_TESS_GEN_VERTEX_ORDER,GL_CCW},{GL_TESS_GEN_POINT_MODE,GL_FALSE}}};report<<",\"tess_layout\":[";for(std::size_t i=0;i<layout.size();++i){GLint value=0;glGetProgramiv(id,layout[i].first,&value);require(value==layout[i].second,"actual tess layout differs");if(i)report<<',';report<<value;}report<<']';}
    if(feedback){GLint countFields=0,mode=0;glGetProgramiv(id,GL_TRANSFORM_FEEDBACK_VARYINGS,&countFields);glGetProgramiv(id,GL_TRANSFORM_FEEDBACK_BUFFER_MODE,&mode);require(countFields==5&&mode==GL_INTERLEAVED_ATTRIBS,"original VS TF reflection differs");const GLenum fieldTypes[]={GL_FLOAT_VEC4,GL_FLOAT_VEC3,GL_FLOAT,GL_FLOAT,GL_FLOAT};report<<",\"original_VS_TF_fields\":[";
        for(int i=0;i<5;++i){char reflected[256]={};GLsizei length=0;GLint arraySize=0;GLenum type=0;glGetTransformFeedbackVarying(id,GLuint(i),sizeof(reflected),&length,&arraySize,&type,reflected);require(std::string(reflected)==fields[i]&&arraySize==1&&type==fieldTypes[i],"actual original VS TF field/type differs");if(i)report<<',';report<<quote(reflected);}report<<']';}
    report<<'}';for(auto stage:stages)glDeleteShader(stage);glOkay("program link/reflection");return id;
}
