    std::array<std::array<std::string,4>,2> sources={};const char* files[]={"gbuffers_water.vsh","gbuffers_water.tcs","gbuffers_water.tes","gbuffers_water.fsh"};for(int variant=0;variant<2;++variant){const auto& root=variant?testRoot:controlRoot;const auto metadata=readText(root.parent_path()/"WATER-TESSELLATION-PROBE.json");require(std::regex_search(metadata,std::regex("\"level\"\\s*:\\s*4\\s*[,}]"))&&std::regex_search(metadata,std::regex("\"fixed_phase_seconds\"\\s*:\\s*120\\.0\\s*[,}]")),"factor4/phase120 parent required");for(int i=0;i<4;++i)sources[variant][i]=expand(root/files[i],root);require(sources[variant][0].find("#define frameTimeCounter 120.0\n")!=std::string::npos&&sources[variant][3].find("#define frameTimeCounter 120.0\n")!=std::string::npos,"compiled fixed phase120 missing");}
